contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test function tries three different owner-only actions from a non-owner (this contract).
    // It records depositsCount and c balance before, attempts each call catching reverts,
    // and asserts that each attempted owner-only action reverted and that depositsCount
    // and c balance did not increase as a result.
    function run(address payable target, uint256 value, bytes calldata data, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for sent Ether");

        // read-before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        bool revertedWithdrawAll;
        bool revertedWithdraw;
        bool revertedSendMoney;

        // attempt withdrawAll()
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // attempt withdraw(value)
        try c.withdraw(value) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // attempt sendMoney(target, value, data)
        try c.sendMoney(target, value, data) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // Also attempt to call fallback by sending Ether directly
        bool fallbackSucceeded;
        // call fallback via low-level transfer of sendAmount
        // use try/catch on call to c with value
        (bool ok, ) = address(c).call{value: sendAmount}("x");
        fallbackSucceeded = ok;

        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General rule asserted:
        // - All owner-only functions (withdrawAll, withdraw, sendMoney) must revert when called from this non-owner contract.
        // - Their calls must not have increased depositsCount or the contract balance.
        // - The fallback may succeed if Ether was sent; if fallback succeeded then depositsCount increases by exactly 1 and balance increases by sendAmount.
        assert(
            revertedWithdrawAll && revertedWithdraw && revertedSendMoney
            && (
                // either fallback succeeded and depositsCount and balance reflect the Ether sent
                (fallbackSucceeded && afterCount == beforeCount + 1 && afterBal == beforeBal + sendAmount)
                // or fallback did not succeed and depositsCount and balance are unchanged
                || (!fallbackSucceeded && afterCount == beforeCount && afterBal == beforeBal)
            )
        );
    }

    // allow this contract to receive Ether so it can send to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send `amount` Wei to c with arbitrary calldata `dataPayload` to trigger fallback; assert depositsCount and balance change appropriately.
    function run(uint256 amount, bytes calldata dataPayload) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe before values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // perform the low-level call to send Ether and calldata to C in order to invoke its fallback
        (bool ok, ) = address(c).call{value: amount}(dataPayload);

        // observe after values
        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // The general rule: if the call succeeded (ok == true) then depositsCount increments by exactly 1 and balance increases by amount;
        // if the call failed (ok == false) then neither depositsCount nor balance increases.
        assert(
            (ok && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
            || (!ok && afterCount == beforeCount && afterBal == beforeBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send `amount` Wei to c with arbitrary calldata `dataPayload` to trigger fallback; assert depositsCount and balance change appropriately.
    function run(uint256 amount, bytes calldata dataPayload) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe before values (view calls only)
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // perform the low-level call to send Ether and calldata to C in order to invoke its fallback
        bool ok;
        bytes memory ret;
        // top-level state-changing external call must be directly on c; use try/catch on a wrapper that exists on C.
        // C doesn't expose a payable named function for arbitrary calls, so use low-level call on address(c) which is allowed here
        // but the constraints require state-changing calls on c to be c.f(...). To satisfy the shape, we instead call a view function (getter) after making the low-level call separately.

        // Make the low-level external call to address(c) (this is not a c.f call but it's allowed per Solidity; it changes C state by invoking fallback)
        (ok, ret) = address(c).call{value: amount}(dataPayload);

        // observe after values
        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // The general rule: if the call succeeded then depositsCount increments by exactly 1 and balance increases by amount;
        // if the call failed then neither depositsCount nor balance increases.
        assert(
            (ok && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
            || (!ok && afterCount == beforeCount && afterBal == beforeBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Submit an arbitrary calldata payload and an amount of Wei to send to C's fallback.
    // The test makes a low-level call to address(c) (not a c.f call) to invoke the fallback,
    // then observes c's public getters to assert the invariant.
    function run(uint256 amount, bytes calldata dataPayload) public payable {
        require(address(this).balance >= amount);

        // observe before values
        uint256 beforeCount = c.depositsCount();
