            if (anyOwnerCallSucceeded) {
                // If any succeeded, contract balance cannot be greater than before + sendAmount (no unexpected inflow)
                assert(afterDeposits == beforeDeposits + 1 && balAfter <= balBefore + sendAmount);
            } else {
                // All reverted despite being owner: still depositsCount change must hold
                assert(afterDeposits == beforeDeposits + 1);
            }
        }
    }

    // Allow receiving Ether so this test can fund calls
    receive() external payable {}

    // Provide access to C's fallback by defining a function that forwards value — but we must call c.fallback{value:...}() directly
    fallback() external payable {}
}

