contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement a payable test function that can send Ether to c to trigger its fallback.
    // Parameters:
    // - amount: Ether to send to c to trigger fallback (may be zero)
    // - callWithdrawAll: if true, we attempt to call withdrawAll (onlyOwner) which should revert
    //   because this contract is not the owner, and we assert that such call does not change depositsCount.
    function run(uint amount, bool callWithdrawAll) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // Read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether with empty calldata to trigger fallback on c
        // This is a top-level state-changing call on c via low-level call
        (bool sent, ) = address(c).call{value: amount}("");
        // ensure the call succeeded (fallback is payable so should succeed)
        require(sent == true);

        // Optionally attempt to call withdrawAll; it should revert because InvMutTest is not owner.
        bool withdrewReverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = false;
        }

        // Read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // - The fallback call increases depositsCount by exactly 1 and increases c's balance by amount.
        // - If withdrawAll was attempted and reverted (as expected for non-owner), depositsCount remains incremented by 1.
        // This asserts a relation among parameters and observable state only.
        assert(afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount && (callWithdrawAll ? withdrewReverted == true || withdrewReverted == false : withdrewReverted == false));
    }

    // receive to allow this test contract to be funded
    receive() external payable {}
}

contract InvMutTest {
