        // - contract balance increases by exactly amount
        // - if we attempted withdrawAll, it must revert because this contract is not the owner
        assert(afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount && (tryWithdrawAll ? withdrewReverted == true : true));
    }

    // allow this test contract to be funded
