contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The single public test function takes an amount to send to the fallback and a gasless data payload.
    // We require this contract to hold enough Ether to forward `amount` to c.
    function run(uint256 amount, bytes calldata data) public payable {
        require(address(this).balance >= amount);

        // Read before-values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // Call fallback by sending Ether with empty calldata (but we allow data to be passed to call target via sendMoney later if desired).
        // Use low-level call to invoke fallback: calling address(c).call with empty calldata triggers fallback.
        bool success;
        if (amount > 0) {
            // send Ether to trigger fallback payable
            (success, ) = address(c).call{value: amount}("\x00");
        } else {
            // zero value call; still attempt to invoke fallback with empty calldata
            (success, ) = address(c).call("");
        }
        // We don't require success: fallback is payable so success is expected, but keep as observable flag.

        // Read after-values
        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General invariant asserting how depositsCount and balance change depending on amount
        // If amount > 0 and the call succeeded then depositsCount increased by exactly 1 and balance increased by amount.
        // If amount == 0 then neither depositsCount nor balance changed (call may succeed or not but should not alter these values).
        assert(
            (amount > 0 && success && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
            || (amount == 0 && afterCount == beforeCount && afterBal == beforeBal)
        );
    }

    // Allow receiving Ether to fund this test contract if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to test withdrawAll behavior when called by this contract (which is the owner)
    // and also observe revert behavior when calling withdrawAll as a non-owner via a try/catch (simulated by a call from this contract after changing owner is impossible,
    // so we instead check that withdraw(uint) reverts when non-owner attempt is simulated by using an external call pattern cannot be done here —
    // therefore we focus on the concrete owner-call property: withdrawAll empties the contract balance and does not change depositsCount.
    function run(uint256 seedDeposit, uint256 sendValue) public payable {
        // Ensure this test contract has enough Ether to fund sending to c
        require(address(this).balance >= sendValue + seedDeposit);

        // Fund c by calling fallback via the provided public payable interface: send Ether to c using c.sendMoney to itself is not allowed (onlyOwner),
        // but sending Ether directly to c (address transfer) will invoke its fallback. However the constraints require state-changing calls to be top-level calls on c.
        // So we instead use the provided onlyOwner functions: this contract is the owner of c, so we can call c.sendMoney to send Ether from c to a target.
        // To seed c's balance we first send Ether to c by calling c with value via its fallback: this must be done as a top-level low-level call is not allowed by rules,
        // but calling payable functions on c with value must be via c.f{value:...}(...). c has no payable named function except fallback, which is invoked by empty calldata on address(c).call —
        // that is not allowed. To respect the requirement that all state-changing interactions with c are of the form c.f(...), we will instead rely on the fact that the freshly deployed c may have zero balance,
        // so we first call c.sendMoney to move zero (a valid owner call) to a neutral address, then we directly invoke withdrawAll to observe its effect when balance is zero and when balance is positive.

        // Read before-values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // If caller (this) is owner, calling withdrawAll should withdraw the entire balance to msg.sender (this contract), leaving c balance zero.
        // Execute the owner call withdrawAll as a top-level state-changing call.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General rule: when the owner (this contract) calls withdrawAll it must not revert, it must set contract balance to zero, and must not change depositsCount.
        // We require reverted == false in the assert to ensure the successful-owner-path is enforced as part of the property.
        assert(reverted == false && afterBal == 0 && afterCount == beforeCount);
    }

    // Allow receiving Ether so withdrawAll transfers Ether here
    receive() external payable {}
}

