contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary target amount to send to c's fallback.
    // The test contract must hold at least `amount` before calling.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Call fallback by sending a plain value transfer to c
        bool reverted;
        // perform low-level call to trigger fallback
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // Read after values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if the fallback call did not revert, depositsCount increments by exactly 1
        // and contract balance increases by exactly amount. If it reverted, neither must have changed.
        assert(reverted
            ? (afterCount == beforeCount && afterBal == beforeBal)
            : (afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
        );
    }

    // allow this test contract to receive Ether to fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: target to call, value to send from C, calldata for the call,
    // and an upfront funding amount to ensure C has some balance when needed.
    function run(address target, uint value, bytes calldata data, uint seedFund) public payable {
        // Fund this test contract so it can fund C via fallback on C if needed.
        require(address(this).balance >= seedFund);

        // Ensure this test contract (deployer of C) is the owner of c by construction (checker deploys C with this contract as owner).
        // Precondition: seedFund will be forwarded to C to ensure it has at least `value` if we want a non-reverting send.

        // Record before values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // If seedFund > 0, send Ether to C to increase its balance via its fallback (top-level state-changing call must be c.f(...); pattern)
        if (seedFund > 0) {
            // send Ether to C by calling its fallback: do a payable call to c with empty data
            // This is a top-level external call to c via its fallback using the c.call syntax is not allowed by constraints,
            // but we can invoke the payable fallback by calling address(c).call — however the template requires state-changing calls on c to be c.f(...) only.
            // Instead, C has no explicit payable function except fallback; but we can use the public interface: calling fallback must be via low-level call.
            // To satisfy the constraint that state-changing calls on c be top-level, we will instead call c.sendMoney to have C send to target; funding C must be done by requiring seedFund == 0 or that C already has balance.
            // So restrict: require seedFund == 0 to avoid needing to fund C here.
            revert();
        }

        // Perform the tested state-changing call: try c.sendMoney(value) invoked by this contract (owner). Must be top-level.
        bool didRevert;
        try c.sendMoney(target, value, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if sendMoney succeeded, C's balance decreased by exactly value and depositsCount is unchanged.
        // If sendMoney reverted, neither balance nor depositsCount changed.
        assert(didRevert
            ? (afterCount == beforeCount && afterBal == beforeBal)
            : (afterCount == beforeCount && beforeBal >= value && afterBal + value == beforeBal)
        );
    }

    // Allow receiving Ether if the test needs it (not used here).
    receive() external payable {}
}

